package detect

//go:generate uv run --script ../../scripts/gen_lists.py --only tlds,suffixes

import (
	_ "embed"
	"strings"
	"sync"
)

// The lists in data/ are generated by scripts/gen_lists.py from public-domain
// sources (see data/SOURCES). Entries are lowercase, one per line.

//go:embed data/tlds.txt
var tldsTXT string

//go:embed data/street_suffixes.txt
var streetSuffixesTXT string

// lineSet parses a one-entry-per-line list into a set.
func lineSet(data string) map[string]struct{} {
	lines := strings.Split(data, "\n")
	set := make(map[string]struct{}, len(lines))
	for _, l := range lines {
		if l != "" {
			set[l] = struct{}{}
		}
	}
	return set
}

var embeddedTLDs = sync.OnceValue(func() map[string]struct{} { return lineSet(tldsTXT) })

var embeddedStreetSuffixes = sync.OnceValue(func() map[string]struct{} { return lineSet(streetSuffixesTXT) })

// tldKnown reports whether label is an IANA top-level domain, ignoring case.
func tldKnown(label string) bool {
	_, ok := embeddedTLDs()[strings.ToLower(label)]
	return ok
}

// isStreetSuffix reports whether lower, a lowercase word without a trailing
// '.', is a USPS street suffix: a primary name, a common form or the
// standard abbreviation.
func isStreetSuffix(lower string) bool {
	_, ok := embeddedStreetSuffixes()[lower]
	return ok
}
